### 2. Fetch the Presigned URL using the file name and type [Link to 2. Fetch the Presigned URL using the file name and type](https://neon.com/guides/next-upload-aws-s3#2-fetch-the-presigned-url-using-the-file-name-and-type)
```
// File: app/page.tsx

'use client';

import { ChangeEvent } from 'react';

export default function Home() {
  const uploadFile = (e: ChangeEvent<HTMLInputElement>) => {
    const file: File | null | undefined = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      const fileData = event.target?.result;
      if (fileData) {
        const presignedURL = new URL('/api/presigned', window.location.href);
        presignedURL.searchParams.set('fileName', file.name);
        presignedURL.searchParams.set('contentType', file.type);
        fetch(presignedURL.toString())
          .then((res) => res.json())
          .then((res) => {
            const body = new Blob([fileData], { type: file.type });
            fetch(res.signedUrl, {
              body,
              method: 'PUT',
            }).then(() => {
              // Save reference to the object in Postgres (powered by Neon)
            });
          });
      }
    };
    reader.readAsArrayBuffer(file);
  };
  return <input onChange={uploadFile} type="file" />;
}
```

## How Do I Generate a Presigned URL for Uploads? [​](https://www.tigrisdata.com/docs/ai-agents/nextjs-file-uploads/#how-do-i-generate-a-presigned-url-for-uploads)
```ts
// app/api/presign/route.ts

import { NextRequest, NextResponse } from "next/server";

import { PutObjectCommand } from "@aws-sdk/client-s3";

import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

import { s3Client, BUCKET_NAME } from "@/lib/tigris";

export async function POST(request: NextRequest) {

  const { filename, contentType } = await request.json();

  const key = `uploads/${Date.now()}-${filename}`;

  const url = await getSignedUrl(

    s3Client,

    new PutObjectCommand({

      Bucket: BUCKET_NAME,

      Key: key,

      ContentType: contentType,

    }),

    { expiresIn: 3600 },

  );

  return NextResponse.json({ url, key });

}
```

## How Do I Upload Directly from the Browser? [​](https://www.tigrisdata.com/docs/ai-agents/nextjs-file-uploads/#how-do-i-upload-directly-from-the-browser)
```tsx
async function uploadWithPresignedUrl(file: File) {

  // Get presigned URL from your API

  const res = await fetch("/api/presign", {

    method: "POST",

    headers: { "Content-Type": "application/json" },

    body: JSON.stringify({

      filename: file.name,

      contentType: file.type,

    }),

  });

  const { url, key } = await res.json();

  // Upload directly to Tigris

  await fetch(url, {

    method: "PUT",

    body: file,

    headers: { "Content-Type": file.type },

  });

  return key;

}
```
